+      .padding({
+        left: this.vm.breakPointModel.pagePadding,
+        right: this.vm.breakPointModel.pagePadding,
+        top: this.vm.windowModel.windowTopPadding + 56,
+        bottom: this.vm.isTabVertical ? 0 : 48
       })
     }
     .width('100%')

